testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { calcularCobertura, invariantesDeOrdenacao } from './solution.mjs';

test('calcularCobertura calcula a porcentagem com 1 casa', () => {
  assert.equal(calcularCobertura(75, 100), 75);
  assert.equal(calcularCobertura(30, 40), 75);
  assert.equal(calcularCobertura(1, 3), 33.3);
});

test('calcularCobertura lança com valores inválidos', () => {
  assert.throws(() => calcularCobertura(-1, 100));
  assert.throws(() => calcularCobertura(10, 0));
  assert.throws(() => calcularCobertura(101, 100));
  assert.throws(() => calcularCobertura('10', 100));
});

test('invariantesDeOrdenacao aceita uma ordenação correta', () => {
  assert.deepEqual(invariantesDeOrdenacao([3, 1, 2], [1, 2, 3]), []);
  assert.deepEqual(invariantesDeOrdenacao([], []), []);
});

test('invariantesDeOrdenacao detecta tamanho, elementos e ordem errados', () => {
  assert.deepEqual(invariantesDeOrdenacao([3, 1, 2], [1, 2]), ['tamanho_mudou']);
  assert.deepEqual(invariantesDeOrdenacao([3, 1, 2], [1, 2, 4]), ['elementos_diferentes']);
  assert.deepEqual(invariantesDeOrdenacao([3, 1, 2], [1, 3, 2]), ['nao_ordenada']);
});

solutionCode:
export function calcularCobertura(executadas, total) {
  if (
    typeof executadas !== 'number' || typeof total !== 'number' ||
    !Number.isFinite(executadas) || !Number.isFinite(total) ||
    executadas < 0 || total <= 0 || executadas > total
  ) {
    throw new Error('valores inválidos: 0 <= executadas <= total e total > 0');
  }
  return Math.round((executadas / total) * 1000) / 10;
}

export function invariantesDeOrdenacao(original, ordenada) {
  const problemas = [];
  const ehLista = Array.isArray(original) && Array.isArray(ordenada);
  if (!ehLista) {
    problemas.push('tamanho_mudou');
    return problemas; // sem listas, não dá para comparar elementos nem ordem
  }
  if (original.length !== ordenada.length) {
    problemas.push('tamanho_mudou');
  } else {
    // multiconjunto: só comparável quando os tamanhos batem
    const a = [...original].sort((x, y) => x - y);
    const b = [...ordenada].sort((x, y) => x - y);
    if (JSON.stringify(a) !== JSON.stringify(b)) {
      problemas.push('elementos_diferentes');
    }
  }
  for (let i = 1; i < ordenada.length; i++) {
    if (ordenada[i - 1] > ordenada[i]) {
      problemas.push('nao_ordenada');
      break;
    }
  }
  return problemas;
}
